-- Corecturi ofertare_normative, varianta A (aprobată de Razvan 02.10.2026). Rulează ca o singură tranzacție.
BEGIN;
INSERT INTO public.ofertare_normative (tip,numar,identificator,titlu,emitent,status,stare,domenii,aplicabilitate,prioritate,sectiune,sursa_verificare,modificari_ulterioare,note) VALUES
('ordin_anre','17/2026','Ordin ANRE 17/2026','Regulament pentru autorizarea operatorilor economici care desfășoară activități în domeniul gazelor naturale (abrogă Ord. 132/2021)','ANRE','in_vigoare','în vigoare din 26.05.2026 (MO 444/26.05.2026)',ARRAY['autorizări'],'tehnic','CRITIC','de adaugat','ANRE — MO 444/26.05.2026 (cercetare 02.10.2026)',NULL,'Înlocuiește Ord. ANRE 132/2021. Art. 39: autorizațiile emise pe Ord. 132/2021 se dovedesc la ANRE până la 26.08.2026 (Gazpet: depuse, confirmat 02.10.2026).'),
('ordin_anre','65/2023','Ordin ANRE 65/2023','Regulament pentru autorizarea persoanelor fizice (înlocuiește Ord. 182/2020) — titlul exact de reconfirmat pe MO','ANRE','in_vigoare','în vigoare (MO 409/12.05.2023)',ARRAY['autorizări'],'tehnic','IMPORTANT','de adaugat','ANRE (cercetare 02.10.2026)','modificat prin Ord. ANRE 85/2024','Înlocuiește Ord. ANRE 182/2020 (instalatori autorizați nominalizați în ofertă).'),
('lege','169/2026','Legea 169/2026','Codul amenajării teritoriului, urbanismului și construcțiilor','Parlament','in_vigoare','în vigoare din 25.08.2026',ARRAY['construcții'],'ambele','IMPORTANT','de adaugat','surse secundare (ISC / lege5) — text oficial de confirmat',NULL,'Abrogă Legea 50/1991 și cea mai mare parte din Legea 10/1995 (rămân art. 10 și 41). HG 273/1994 menținută tranzitoriu (art. 577 alin. (6), de confirmat).')
RETURNING id, identificator;
UPDATE public.ofertare_normative SET status='abrogat', stare='abrogat din 26.05.2026', inlocuit_de='Ordin ANRE 17/2026', note=coalesce(note,'')||E'\n[02.10.2026] Abrogat prin Ord. ANRE 17/2026 (MO 444/26.05.2026).', updated_at=now() WHERE id=22 RETURNING id;
UPDATE public.ofertare_normative SET status='abrogat', stare='abrogat (înlocuit de Ord. ANRE 65/2023)', inlocuit_de='Ordin ANRE 65/2023', note=coalesce(note,'')||E'\n[02.10.2026] Înlocuit de Ord. ANRE 65/2023 (MO 409/12.05.2023), modif. Ord. 85/2024.', updated_at=now() WHERE id=23 RETURNING id;
UPDATE public.ofertare_normative SET status='abrogat', stare='abrogat din 25.08.2026', inlocuit_de='Legea 169/2026', note=coalesce(note,'')||E'\n[02.10.2026] Abrogată de Legea 169/2026, din 25.08.2026.', updated_at=now() WHERE id=20 RETURNING id;
UPDATE public.ofertare_normative SET status='abrogat', stare='abrogată parțial din 25.08.2026 (rămân art. 10 și 41)', inlocuit_de='Legea 169/2026 (parțial)', note=coalesce(note,'')||E'\n[02.10.2026] Abrogată parțial de Legea 169/2026; rămân art. 10 și 41 (de confirmat pe textul oficial).', updated_at=now() WHERE id=4 RETURNING id;
UPDATE public.ofertare_normative SET identificator='Ordin ANRE 8/2025', numar='8/2025', note=coalesce(note,'')||E'\n[02.10.2026] Identificator corectat: Ordin ANRE 8/2025 (MO 378/29.04.2025).', updated_at=now() WHERE id=27 RETURNING id;
