UPDATE public.ofertare_normative SET identificator='SR EN ISO 3834-2:2021', numar='3834-2:2021', modificari_ulterioare='ediția 2021 (2006 anulată); vezi și EN ISO 3834-6:2024', updated_at=now() WHERE id=34 RETURNING id;
